"name": "Washington (US)", "value": 1.7}], "geo": "metros", "measure": "percapita", "tier": 1, "excl_inus": false}, "metros_percapita_tier2": {"title": "Top 25 metropolitan areas by AI talent per capita \u2014 Tier 2", "data": [{"name": "San Jose (US)", "value": 3.47}, {"name": "San Francisco (US)", "value": 2.12}, {"name": "Seattle (US)", "value": 1.8}, {"name": "Amsterdam (NL)", "value": 1.4}, {"name": "Frankfurt Am Main (DE)", "value": 0.83}, {"name": "Boston (US)", "value": 0.73}, {"name": "Stuttgart (DE)", "value": 0.72}, {"name": "Austin (US)", "value": 0.69}, {"name": "Rotterdam (NL)", "value": 0.65}, {"name": "Stockholm (SE)", "value": 0.62}, {"name": "Edinburgh (GB)", "value": 0.61}, {"name": "Bengaluru (IN)", "value": 0.55}, {"name": "Kitchener (CA)", "value": 0.49}, {"name": "London (GB)", "value": 0.48}, {"name": "Berlin (DE)", "value": 0.46}, {"name": "Raleigh (US)", "value": 0.42}, {"name": "Pittsburgh (US)", "value": 0.42}, {"name": "Toulouse (FR)", "value": 0.41}, {"name": "Seoul (KR)", "value": 0.4}, {"name": "Helsinki (FI)", "value": 0.4}, {"name": "Basel (CH)", "value": 0.4}, {"name": "Bristol (GB)", "value": 0.37}, {"name": "Paris (FR)", "value": 0.36}, {"name": "Washington (US)", "value": 0.34}, {"name": "Denver (US)", "value": 0.34}], "geo": "metros", "measure": "percapita", "tier": 2, "excl_inus": false}};

var state = { geo: 'countries', measure: 'absolute', tier: 1, exclInUs: false };

function getKey(g,m,t,e) { var k=g+'_'+m+'_tier'+t; if(e) k+='_excl'; return k; }
function hasData(g,m,t,e) { return !!CHART_DATA[getKey(g,m,t,e)]; }
function getAvailTiers(g,m) { var t=[]; for(var i=0;i<=2;i++) if(hasData(g,m,i,false)||hasData(g,m,i,true)) t.push(i); return t; }

function formatVal(v,m) {
  if(m==='percapita') return v.toFixed(2);
  if(v>=1000) { var s=Math.round(v).toString(),r=''; for(var i=s.length-1,c=0;i>=0;i--,c++) { if(c>0&&c%3===0) r=','+r; r=s[i]+r; } return r; }
  return v.toString();
}

function updateToggle(gid,val) { var b=document.getElementById(gid).querySelectorAll('.toggle-btn'); for(var i=0;i<b.length;i++) { if(b[i].getAttribute('data-val')===String(val)) b[i].classList.add('active'); else b[i].classList.remove('active'); } }

function updateTierDisabled() {
  var a=getAvailTiers(state.geo,state.measure);
  var b=document.getElementById('tier-group').querySelectorAll('.toggle-btn');
  for(var i=0;i<b.length;i++) { var t=parseInt(b[i].getAttribute('data-val')); b[i].disabled=a.indexOf(t)===-1; if(b[i].disabled) b[i].classList.remove('active'); }
  if(a.indexOf(state.tier)===-1) { state.tier=a[0]||1; updateToggle('tier-group',state.tier); }
}

function updateExcl() {
  var ce=hasData(state.geo,state.measure,state.tier,true), hm=hasData(state.geo,state.measure,state.tier,false);
  var c=document.getElementById('excl-container');
  if(ce&&hm) c.style.display='block'; else { c.style.display='none'; if(!hm&&ce) state.exclInUs=true; else state.exclInUs=false; }
  var tk=document.getElementById('excl-track'); if(state.exclInUs) tk.classList.add('on'); else tk.classList.remove('on');
}

function render() {
  updateTierDisabled(); updateExcl();
  var key=getKey(state.geo,state.measure,state.tier,state.exclInUs);
  var chart=CHART_DATA[key]; if(!chart) return;
  document.getElementById('chart-title').textContent=chart.title;
  document.getElementById('axis-label').textContent=state.measure==='percapita'?'PER 1,000 INHABITANTS':'AI TALENT (HEADCOUNT)';
  var area=document.getElementById('chart-area'); while(area.firstChild) area.removeChild(area.firstChild);
  var data=chart.data, maxVal=0, ns='http://www.w3.org/2000/svg';
  for(var i=0;i<data.length;i++) if(data[i].value>maxVal) maxVal=data[i].value;
  var barH=data.length>20?26:28, labelW=160, barAreaW=440, barX=labelW+8;
  for(var i=0;i<data.length;i++) {
    var d=data[i], y=i*barH, w=(d.value/maxVal)*barAreaW;
    var t=document.createElementNS(ns,'text'); t.setAttribute('x',labelW); t.setAttribute('y',y+barH/2+4); t.setAttribute('text-anchor','end'); t.setAttribute('font-size','12.5'); t.setAttribute('font-weight','500'); t.setAttribute('fill','#2a2a2a'); t.textContent=d.name; area.appendChild(t);
    var r=document.createElementNS(ns,'rect'); r.setAttribute('x',barX); r.setAttribute('y',y+3); r.setAttribute('width','0'); r.setAttribute('height',barH-8); r.setAttribute('rx','3'); r.setAttribute('fill','#6c9fc6'); r.classList.add('bar-rect'); area.appendChild(r);
    (function(r2,tw,dl){ setTimeout(function(){ r2.setAttribute('width',tw); },dl); })(r,w,i*15+30);
    var v=document.createElementNS(ns,'text'); v.setAttribute('x',barX+w+8); v.setAttribute('y',y+barH/2+4); v.setAttribute('text-anchor','start'); v.setAttribute('font-size','11.5'); v.setAttribute('font-weight','600'); v.setAttribute('fill','#4a4a4a'); v.textContent=formatVal(d.value,state.measure); area.appendChild(v);
  }
  var totalH=data.length*barH+200; var svg=document.querySelector('svg'); svg.setAttribute('height',totalH); svg.setAttribute('viewBox','0 0 720 '+totalH);
  document.getElementById('source-line').setAttribute('y1',totalH-28); document.getElementById('source-line').setAttribute('y2',totalH-28);
  document.getElementById('source-text').setAttribute('y',totalH-12);
}

function setGeo(v) { state.geo=v; updateToggle('geo-group',v); render(); }
function setMeasure(v) { state.measure=v; updateToggle('measure-group',v); render(); }
function setTier(v) { var a=getAvailTiers(state.geo,state.measure); if(a.indexOf(v)===-1) return; state.tier=v; updateToggle('tier-group',v); render(); }
function toggleExcl() { state.exclInUs=!state.exclInUs; render(); }

setTimeout(render,100);
//
